def divide_list_evenly(lst, n):
    total_sum = sum(lst)
    if total_sum % n != 0:
        return False
    target_sum = total_sum // n
    current_sum = 0
    counter = 0
    for i in range(len(lst)):
        current_sum += lst[i]
        if i >= n:
            current_sum -= lst[i - n]
        if i >= n - 1 and current_sum == target_sum:
            counter += 1
    return counter == n

