def sum_of_squares(n):
    """Calculates the sum of the squares of the digits of a number."""
    return sum(int(i)**2 for i in str(n))

def is_happy(n):
    """Checks if a number is happy or not."""
    seen = set()
    while n != 1 and n not in seen:
        seen.add(n)
        n = sum_of_squares(n)
    return n == 1

def first_n_happy_numbers(n):
    """Prints the first n happy numbers."""
    count, num = 0, 1
    while count < n:
        if is_happy(num):
            print(num)
            count += 1
        num += 1

